import 'dart:convert';
import 'dart:io';

/// Loads a fixture generated by the Swift FixtureExporter (`crossplatform/fixtures`).
Object? loadFixture(String name) {
  final candidates = ['../fixtures/$name', 'fixtures/$name', '../../fixtures/$name'];
  for (final c in candidates) {
    final f = File(c);
    if (f.existsSync()) return jsonDecode(f.readAsStringSync());
  }
  throw StateError('Fixture not found: $name (cwd ${Directory.current.path})');
}

Map<String, Object?> fixtureMap(String name) => (loadFixture(name) as Map).cast<String, Object?>();

List<Map<String, Object?>> casesOf(Object? list) =>
    (list as List).map((e) => (e as Map).cast<String, Object?>()).toList();

/// Numbers: last-bit differences only (relative 1e-12, never more than 1 µs absolute, so dates are
/// effectively exact). Swift omits nil optionals: a key the fixture lacks must be absent in the
/// actual output too (an explicit null is a difference); an explicit null in the fixture matches
/// null or absent.
List<String> jsonDiff(Object? actual, Object? expected, [String path = r'$']) {
  final diffs = <String>[];
  void walk(Object? a, Object? e, String p) {
    if (e is num && a is num) {
      final x = a.toDouble(), y = e.toDouble();
      final rel = 1e-12 * (y.abs() > 1 ? y.abs() : 1);
      if (x == y || (x - y).abs() <= (rel < 1e-6 ? rel : 1e-6)) return;
      diffs.add('$p: $a != $e');
      return;
    }
    if (e is Map && a is Map) {
      final keys = {...e.keys, ...a.keys};
      for (final k in keys) {
        if (!e.containsKey(k) && a.containsKey(k) && a[k] == null) {
          diffs.add('$p.$k: explicit null (Swift omits the key)');
          continue;
        }
        walk(a[k], e[k], '$p.$k');
      }
      return;
    }
    if (e is List && a is List) {
      if (a.length != e.length) {
        diffs.add('$p: length ${a.length} != ${e.length} (actual ${jsonEncode(a)})');
        return;
      }
      for (var i = 0; i < e.length; i++) {
        walk(a[i], e[i], '$p[$i]');
      }
      return;
    }
    if (a != e) diffs.add('$p: ${jsonEncode(a)} != ${jsonEncode(e)}');
  }

  walk(actual, expected, path);
  return diffs;
}

/// Round-trips through JSON so Dart objects compare as plain maps/lists.
Object? plain(Object? v) => jsonDecode(jsonEncode(v));
